  public void refreshOutput()
  {
    int size = this.getConfiguration().getSize();
    java.util.ArrayList<java.util.List<String>> contents = new java.util.ArrayList<java.util.List<String>>();
    for (int row = size - 1; row >= 0; row--) {
        java.util.ArrayList<String> rowContent = new java.util.ArrayList<String>();
        for (int col = 0; col < size; col++) {
            Piece piece = this.getPiece(col, row);
            if (piece == null) {
                // EMF适配：不使用 new Place()，而是直接获取中心点对比坐标值
                Place centralPlace = this.getConfiguration().getCentralPlace();
                if (centralPlace != null && centralPlace.getX() == col && centralPlace.getY() == row) {
                    rowContent.add("x");
                } else {
                    rowContent.add(".");
                }
            } else {
                Player player = piece.getPlayer();
                rowContent.add(String.format("%s%c%s",
                        player.getColor(),
                        piece.getLabel(),
                        Color.DEFAULT)); // 注意：如果在Impl中找不到Color，需改为全限定包名如 edu.pa20.Color.DEFAULT
            }
        }
        contents.add(rowContent);
    }
    java.util.ArrayList<String> xCoordinates = new java.util.ArrayList<String>();
    for (int i = 0; i < size; i++) {
        xCoordinates.add(String.valueOf((char) ('a' + i)));
    }
    java.util.Collections.reverse(contents);
    
    // clear screen
    System.out.print("\u001b[2J");
    System.out.flush();
    
    System.out.println();
    System.out.println("### COMP3021 Programming Assignment 1 ###");
    System.out.println();
    System.out.println("Guide: to move a piece, input the coordinate of source and the destination.");
    System.out.println("For example: a1->b2 means to move the piece at 'a1' to 'b2'");
    
    if (this.getNumMoves() < this.getConfiguration().getNumMovesProtection()) {
        System.out.println();
        System.out.println("Notice: first " + this.getConfiguration().getNumMovesProtection() + " moves are not allowed to capture pieces or win the game.");
    }
    System.out.println();
    System.out.println("Total Moves: " + this.getNumMoves());
    
    // print scores of players
    for (Player player : this.getConfiguration().getPlayers()) {
        System.out.printf("%s%s%s score: %d\n", player.getColor(), player.getName(), Color.DEFAULT, player.getScore());
    }
    System.out.println();
    
    // print the gameboard
    int leftPadding = 8;
    StringBuilder paddingSpaceBuilder = new StringBuilder();
    paddingSpaceBuilder.append(" ".repeat(leftPadding));
    System.out.printf("%s%s\n",
            paddingSpaceBuilder.toString(),
            xCoordinates.parallelStream().collect(java.util.stream.Collectors.joining(" ")));
    
    StringBuilder borderBuilder = new StringBuilder();
    borderBuilder.append("-".repeat(Math.max(0, contents.get(0).size() * 2 - 1)));
    System.out.printf("%s%s\n",
            paddingSpaceBuilder.toString(),
            borderBuilder.toString());
    
    for (int row = contents.size() - 1; row >= 0; row--) {
        System.out.printf("%" + (leftPadding - 1) + "d|%s|%d\n",
                row + 1,
                contents.get(row).parallelStream().map(Object::toString).collect(java.util.stream.Collectors.joining(" ")),
                row + 1);
    }
    System.out.printf("%s%s\n",
            paddingSpaceBuilder.toString(),
            borderBuilder.toString());
    System.out.printf("%s%s\n",
            paddingSpaceBuilder.toString(),
            xCoordinates.parallelStream().collect(java.util.stream.Collectors.joining(" ")));
    System.out.println();
  }

